CREATE TABLE postfinance_observation_jobs ( job_id TEXT PRIMARY KEY NOT NULL, scope_hash TEXT NOT NULL, period_id TEXT NOT NULL REFERENCES prepaid_transactions(period_id), api_origin TEXT NOT NULL,space_id INTEGER NOT NULL,environment TEXT NOT NULL,transaction_id INTEGER NOT NULL, binding_fingerprint TEXT NOT NULL,binding_json TEXT NOT NULL,provenance TEXT NOT NULL,recovery_evidence_fingerprint TEXT, state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,lease TEXT,lease_until INTEGER NOT NULL DEFAULT 0, due_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,completed_at INTEGER,last_error_code TEXT, CONSTRAINT postfinance_observation_identity CHECK(length(scope_hash)=64 AND scope_hash NOT GLOB '*[^a-f0-9]*' AND job_id=('pfobserve_'||scope_hash) AND length(binding_fingerprint)=64 AND binding_fingerprint NOT GLOB '*[^a-f0-9]*'), CONSTRAINT postfinance_observation_scope CHECK(api_origin IN('https://checkout.postfinance.ch','https://app-wallee.com') AND space_id>0 AND transaction_id>0 AND environment IN('TEST','PRODUCTION')), CONSTRAINT postfinance_observation_json CHECK(json_valid(binding_json) AND json_type(binding_json)='object' AND length(CAST(binding_json AS BLOB))<=16384), CONSTRAINT postfinance_observation_provenance CHECK((provenance='bound_fallback' AND recovery_evidence_fingerprint IS NULL) OR(provenance='create_recovery' AND length(recovery_evidence_fingerprint)=64 AND recovery_evidence_fingerprint NOT GLOB '*[^a-f0-9]*')), CONSTRAINT postfinance_observation_state CHECK(state IN('pending','processing','completed','failed') AND attempts BETWEEN 0 AND 8 AND ((state='processing' AND lease IS NOT NULL AND length(lease)=36 AND lease_until>0 AND attempts>0) OR(state!='processing' AND lease IS NULL AND lease_until=0))), CONSTRAINT postfinance_observation_time CHECK(created_at>0 AND updated_at>=created_at AND due_at>0 AND (completed_at IS NULL OR(state='completed' AND completed_at=updated_at)) AND (state!='completed' OR completed_at IS NOT NULL)), CONSTRAINT postfinance_observation_error CHECK(last_error_code IS NULL OR last_error_code IN('provider_unavailable','settlement_pending','ownership_mismatch','ambiguous_period','invalid_provider_state','storage_unavailable')) );
--> statement-breakpoint
CREATE UNIQUE INDEX postfinance_observation_scope_unique ON postfinance_observation_jobs(scope_hash);
--> statement-breakpoint
CREATE UNIQUE INDEX postfinance_observation_period_unique ON postfinance_observation_jobs(period_id);
--> statement-breakpoint
CREATE INDEX postfinance_observation_due ON postfinance_observation_jobs(api_origin,space_id,environment,state,due_at,lease_until);
--> statement-breakpoint
