:null,"support":{"planId":"team","analyses":5000},"automation":false,"catalogVersion":"zentra-prepaid-chf-monthly-v1","scope":"organization","currency":"CHF","billingPeriod":"P1M"}'),('support:business','{"productKey":"support:business","productKind":"support","planId":"business","name":"Zentra Support Business","priceChfMinor":9900,"includedProducts":["support"],"gestion":null,"support":{"planId":"business","analyses":15000},"automation":false,"catalogVersion":"zentra-prepaid-chf-monthly-v1","scope":"organization","currency":"CHF","billingPeriod":"P1M"}'),('automation','{"productKey":"automation","productKind":"automation","planId":"zentra_automation","name":"Zentra Automation","priceChfMinor":1500,"includedProducts":["automation"],"gestion":null,"support":null,"automation":true,"catalogVersion":"zentra-prepaid-chf-monthly-v1","scope":"organization","currency":"CHF","billingPeriod":"P1M"}'),('complet:solo','{"productKey":"complet:solo","productKind":"complete","planId":"solo","name":"Zentra Complet Solo","priceChfMinor":7900,"includedProducts":["gestion","support","automation"],"gestion":{"planId":"solo","licensePlan":"zentra-solo-monthly-49-chf","licensePriceChfMinor":4900,"seats":1,"ownerIncluded":true},"support":{"planId":"starter","analyses":2000},"automation":true,"catalogVersion":"zentra-prepaid-chf-monthly-v1","scope":"organization","currency":"CHF","billingPeriod":"P1M"}'),('complet:team','{"productKey":"complet:team","productKind":"complete","planId":"team","name":"Zentra Complet Équipe","priceChfMinor":9900,"includedProducts":["gestion","support","automation"],"gestion":{"planId":"start","licensePlan":"zentra-start-monthly-59-chf","licensePriceChfMinor":5900,"seats":3,"ownerIncluded":true},"support":{"planId":"team","analyses":5000},"automation":true,"catalogVersion":"zentra-prepaid-chf-monthly-v1","scope":"organization","currency":"CHF","billingPeriod":"P1M"}'),('complet:pro','{"productKey":"complet:pro","productKind":"complete","planId":"pro","name":"Zentra Complet Pro","priceChfMinor":16900,"includedProducts":["gestion","support","automation"],"gestion":{"planId":"pro","licensePlan":"zentra-pro-monthly-89-chf","licensePriceChfMinor":8900,"seats":10,"ownerIncluded":true},"support":{"planId":"business","analyses":15000},"automation":true,"catalogVersion":"zentra-prepaid-chf-monthly-v1","scope":"organization","currency":"CHF","billingPeriod":"P1M"}'));
