CREATE VIEW prepaid_observation_source_base AS SELECT p.*,c.owner_id,c.organization_id,c.workspace_id,c.api_origin,c.space_id,c.environment,c.anchor_start,c.fingerprint AS contract_fingerprint, e.customer_reference,e.plan_reference,e.payment_method_configuration_id,e.connector_configuration_id,e.fingerprint AS expectation_fingerprint, i.intent_id,i.fingerprint AS intent_fingerprint,x.previous_subscription_id,t.transaction_id,t.created_at AS transaction_created_at, CASE WHEN NOT EXISTS(SELECT 1 FROM account_session_policy a WHERE a.user_id=c.owner_id AND a.deleted_at IS NOT NULL) AND (c.organization_id IS NULL OR EXISTS(SELECT 1 FROM organizations o JOIN organization_members member ON member.organization_id=o.organization_id WHERE o.organization_id=c.organization_id AND o.created_by_user_id=c.owner_id AND member.user_id=c.owner_id AND member.role='owner' AND member.revoked_at IS NULL AND (o.subscription_id=x.previous_subscription_id OR(json_extract(cat.catalog_json,'$.productKind') IN('gestion','complete') AND o.subscription_id=c.contract_id) OR(json_extract(cat.catalog_json,'$.productKind') IN('support','automation') AND EXISTS(SELECT 1 FROM prepaid_purchase_projections closed WHERE closed.contract_id=c.contract_id AND closed.intent_id=i.intent_id AND closed.owner_id=c.owner_id AND closed.organization_id IS c.organization_id AND closed.workspace_id IS c.workspace_id AND closed.closed_at IS NOT NULL))))) AND (c.workspace_id IS NULL OR EXISTS(SELECT 1 FROM support_workspaces w WHERE w.id=c.workspace_id AND w.owner_id=c.owner_id)) AND NOT EXISTS(SELECT 1 FROM support_gestion_links l WHERE(l.organization_id=c.organization_id AND c.workspace_id IS NOT NULL AND l.workspace_id IS NOT c.workspace_id) OR(l.workspace_id=c.workspace_id AND l.organization_id IS NOT c.organization_id)) THEN 1 ELSE 0 END AS current_owner FROM prepaid_periods p JOIN prepaid_contracts c ON c.contract_id=p.contract_id JOIN prepaid_payment_expectations e ON e.period_id=p.period_id JOIN prepaid_purchase_targets x ON x.contract_id=c.contract_id JOIN purchase_intents i ON i.intent_id=x.intent_id JOIN prepaid_observation_catalog_v1 cat ON cat.product_key=c.product_key AND cat.catalog_json=c.catalog_json LEFT JOIN prepaid_transactions t ON t.period_id=p.period_id AND t.api_origin=c.api_origin AND t.space_id=c.space_id WHERE p.catalog_json=c.catalog_json AND p.catalog_version=c.catalog_version AND p.currency='CHF' AND p.price_chf_minor=json_extract(cat.catalog_json,'$.priceChfMinor') AND p.catalog_version=json_extract(cat.catalog_json,'$.catalogVersion') AND e.plan_reference=p.catalog_version AND c.owner_id=i.owner_id AND c.environment=i.environment AND c.organization_id IS i.organization_id AND c.workspace_id IS i.workspace_id AND x.owner_id=c.owner_id AND x.organization_id IS c.organization_id AND x.workspace_id IS c.workspace_id AND i.provider='postfinance' AND i.provider_scope=(c.api_origin||'|'||c.space_id) AND i.product=json_extract(cat.catalog_json,'$.productKind') AND (p.ordinal>0 OR(t.transaction_id IS NULL AND i.provider_reference IS NULL) OR i.provider_reference=CAST(t.transaction_id AS TEXT)) AND json_extract(i.parameters,'$.productKey')=c.product_key AND json_extract(i.parameters,'$.catalogVersion')=c.catalog_version AND json_extract(i.parameters,'$.priceChfMinor')=p.price_chf_minor AND json_extract(i.parameters,'$.name')=json_extract(cat.catalog_json,'$.name') AND json_extract(i.parameters,'$.methodConfigurationId')=e.payment_method_configuration_id AND json_extract(i.parameters,'$.connectorConfigurationId')=e.connector_configuration_id AND json_extract(i.parameters,'$.previousSubscriptionId') IS x.previous_subscription_id AND NOT EXISTS(SELECT 1 FROM json_tree(i.parameters) GROUP BY parent,key HAVING COUNT(*)>1) AND (p.ordinal=0 AND i.state IN('dispatched','uncertain','settled') OR p.ordinal>0 AND i.state='settled' AND EXISTS(SELECT 1 FROM prepaid_purchase_projections v WHERE v.contract_id=c.contract_id AND v.intent_id=i.intent_id AND v.closed_at IS NOT NULL) AND EXISTS(SELECT 1 FROM prepaid_renewal_requests r WHERE r.period_id=p.period_id AND r.contract_id=c.contract_id));
--> statement-breakpoint
CREATE VIEW prepaid_observation_sources AS SELECT b.*,json_object('anchorStart',b.anchor_start,'apiOrigin',b.api_origin,'catalogJson',b.catalog_json,'catalogVersion',b.catalog_version,'connectorConfigurationId',b.connector_configuration_id,'contractFingerprint',b.contract_fingerprint,'contractId',b.contract_id,'currency',b.currency,'customerReference',b.customer_reference,'endsAt',b.ends_at,'environment',b.environment,'expectationFingerprint',b.expectation_fingerprint,'intentFingerprint',b.intent_fingerprint,'intentId',b.intent_id,'ordinal',b.ordinal,'organizationId',b.organization_id,'ownerId',b.owner_id,'paymentMethodConfigurationId',b.payment_method_configuration_id,'periodId',b.period_id,'planReference',b.plan_reference,'previousSubscriptionId',b.previous_subscription_id,'priceChfMinor',b.price_chf_minor,'spaceId',b.space_id,'startsAt',b.starts_at,'transactionId',b.transaction_id,'workspaceId',b.workspace_id) AS binding_json FROM prepaid_observation_source_base b;
--> statement-breakpoint
CREATE TRIGGER postfinance_observation_admission BEFORE INSERT ON postfinance_observation_jobs BEGIN SELECT CASE WHEN NEW.state!='pending' OR NEW.attempts!=0 OR NEW.lease IS NOT NULL OR NEW.lease_until!=0 OR NEW.completed_at IS NOT NULL OR NEW.last_error_code IS NOT NULL OR NEW.created_at>unixepoch() OR NEW.updated_at!=NEW.created_at OR NEW.due_at!=NEW.created_at OR NOT EXISTS(SELECT 1 FROM prepaid_observation_sources s WHERE s.period_id=NEW.period_id AND s.transaction_id=NEW.transaction_id AND s.api_origin=NEW.api_origin AND s.space_id=NEW.space_id AND s.environment=NEW.environment AND s.binding_json=NEW.binding_json AND s.current_owner=1) OR (NEW.provenance='create_recovery' AND NOT EXISTS(SELECT 1 FROM prepaid_create_recoveries r WHERE r.period_id=NEW.period_id AND r.transaction_id=NEW.transaction_id AND r.evidence_fingerprint=NEW.recovery_evidence_fingerprint)) OR EXISTS(SELECT 1 FROM postfinance_observation_jobs j WHERE j.period_id=NEW.period_id AND(j.job_id!=NEW.job_id OR j.scope_hash!=NEW.scope_hash OR j.binding_fingerprint!=NEW.binding_fingerprint OR j.binding_json!=NEW.binding_json OR j.transaction_id!=NEW.transaction_id)) THEN RAISE(ABORT,'postfinance_observation_binding') END; END ;
--> statement-breakpoint
CREATE TRIGGER postfinance_observation_immutable BEFORE UPDATE ON postfinance_observation_jobs BEGIN SELECT CASE WHEN NEW.job_id IS NOT OLD.job_id OR NEW.scope_hash IS NOT OLD.scope_hash OR NEW.period_id IS NOT OLD.period_id OR NEW.api_origin IS NOT OLD.api_origin OR NEW.space_id IS NOT OLD.space_id OR NEW.environment IS NOT OLD.environment OR NEW.transaction_id IS NOT OLD.transaction_id OR NEW.binding_fingerprint IS NOT OLD.binding_fingerprint OR NEW.binding_json IS NOT OLD.binding_json OR NEW.provenance IS NOT OLD.provenance OR NEW.recovery_evidence_fingerprint IS NOT OLD.recovery_evidence_fingerprint OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at<OLD.updated_at OR NEW.updated_at>unixepoch() OR OLD.state IN('completed','failed') OR NOT ((OLD.state='pending' AND NEW.state='processing' AND OLD.due_at<=NEW.updated_at AND NEW.attempts=OLD.attempts+1 AND NEW.lease_until>NEW.updated_at) OR(OLD.state='processing' AND NEW.state='processing' AND NEW.due_at=OLD.due_at AND((OLD.lease_until>NEW.updated_at AND NEW.lease=OLD.lease AND NEW.attempts=OLD.attempts AND NEW.lease_until>NEW.updated_at) OR(OLD.lease_until<=NEW.updated_at AND OLD.attempts<8 AND NEW.attempts=OLD.attempts+1 AND NEW.lease!=OLD.lease AND NEW.lease_until>NEW.updated_at))) OR(OLD.state='processing' AND NEW.state IN('pending','completed') AND OLD.lease_until>NEW.updated_at AND NEW.attempts=OLD.attempts AND(NEW.state='completed' OR NEW.due_at>NEW.updated_at)) OR(OLD.state='processing' AND NEW.state='failed' AND OLD.attempts>=8 AND NEW.attempts=OLD.attempts)) THEN RAISE(ABORT,'postfinance_observation_immutable') END; END ;
--> statement-breakpoint
CREATE TRIGGER postfinance_observation_no_delete BEFORE DELETE ON postfinance_observation_jobs BEGIN SELECT RAISE(ABORT,'postfinance_observation_immutable'); END ;
--> statement-breakpoint
CREATE VIEW prepaid_projection_work_leases AS SELECT scope_hash,state,lease,lease_until,'webhook' AS kind,NULL AS period_id,NULL AS contract_id,NULL AS intent_id,NULL AS owner_id,NULL AS organization_id,NULL AS workspace_id FROM postfinance_webhook_inbox UNION ALL SELECT j.scope_hash,j.state,j.lease,j.lease_until,'observation',j.period_id,s.contract_id,s.intent_id,s.owner_id,s.organization_id,s.workspace_id FROM postfinance_observation_jobs j JOIN prepaid_observation_sources s ON s.period_id=j.period_id AND s.binding_json=j.binding_json WHERE s.current_owner=1;
--> statement-breakpoint
DROP TRIGGER prepaid_purchase_projection_admission;
--> statement-breakpoint
CREATE TRIGGER prepaid_purchase_projection_admission BEFORE INSERT ON prepaid_purchase_projections BEGIN SELECT CASE WHEN NEW . closed_at IS NOT NULL OR NEW . projected_at > unixepoch ( ) OR NOT EXISTS ( SELECT 1 FROM prepaid_initial_purchase_effective b JOIN prepaid_projection_work_leases w ON w . scope_hash = NEW . scope_hash WHERE b . period_id = NEW . period_id AND b . intent_id = NEW . intent_id AND b . contract_id = NEW . contract_id AND b . owner_id = NEW . owner_id AND b . organization_id IS NEW . organization_id AND b . workspace_id IS NEW . workspace_id AND b . evidence_fingerprint = NEW . evidence_fingerprint AND (w . kind = 'webhook' OR (w . period_id = b . period_id AND w . contract_id = b . contract_id AND w . intent_id = b . intent_id AND w . owner_id = b . owner_id AND w . organization_id IS b . organization_id AND w . workspace_id IS b . workspace_id)) AND w . state = 'processing' AND w . lease = NEW . lease AND w . lease_until > unixepoch ( ) ) THEN RAISE ( ABORT , 'prepaid_purchase_projection' ) END ; END ;
--> statement-breakpoint
DROP TRIGGER prepaid_purchase_projection_closure;
--> statement-breakpoint
CREATE TRIGGER prepaid_purchase_projection_closure BEFORE UPDATE ON prepaid_purchase_projections BEGIN SELECT CASE WHEN NEW . period_id IS NOT OLD . period_id OR NEW . intent_id IS NOT OLD . intent_id OR NEW . contract_id IS NOT OLD . contract_id OR NEW . owner_id IS NOT OLD . owner_id OR NEW . organization_id IS NOT OLD . organization_id OR NEW . workspace_id IS NOT OLD . workspace_id OR NEW . projected_at IS NOT OLD . projected_at OR NEW . evidence_fingerprint IS NOT OLD . evidence_fingerprint OR NEW . scope_hash IS NOT OLD . scope_hash OR NEW . lease IS NOT OLD . lease OR OLD . closed_at IS NOT NULL OR NEW . closed_at IS NULL THEN RAISE ( ABORT , 'prepaid_purchase_projection_immutable' ) WHEN NOT EXISTS ( SELECT 1 FROM prepaid_initial_purchase_effective b JOIN purchase_intents i ON i . intent_id = b . intent_id JOIN prepaid_projection_work_leases w ON w . scope_hash = NEW . scope_hash WHERE b . period_id = NEW . period_id AND b . evidence_fingerprint = NEW . evidence_fingerprint AND i . state = 'settled' AND i . evidence_fingerprint = NEW . evidence_fingerprint AND i . finalized_at = NEW . closed_at AND NEW . closed_at >= NEW . projected_at AND NEW . closed_at <= unixepoch ( ) AND (w . kind = 'webhook' OR (w . period_id = b . period_id AND w . contract_id = b . contract_id AND w . intent_id = b . intent_id AND w . owner_id = b . owner_id AND w . organization_id IS b . organization_id AND w . workspace_id IS b . workspace_id)) AND w . state = 'processing' AND w . lease = NEW . lease AND w . lease_until > unixepoch ( ) AND NOT EXISTS ( SELECT 1 FROM purchase_intent_footprints f WHERE f . intent_id = i . intent_id AND f . released_at IS NULL ) ) THEN RAISE ( ABORT , 'prepaid_purchase_projection_incomplete' ) END ; END ;
